/* 模型厂品牌表：色值与 logo 对齐 artificialanalysis.ai 模型页 —— 色值取自 AA 页面
   JSON 的 creator.color，logo 下载自 AA 站点 /img/logos/ 后 base64 内嵌，完全本地离线。
   以后出新模型：名字命中 BRAND_MATCH 前缀就自动有色有标，不用改代码；
   AA 上了新厂时 BRAND 补一行 + BRAND_MATCH 补一条前缀即可。
   dark 是深色主题替代色（只有纯黑会糊进 #191817 底色的 openai 需要）。 */
const BRAND = {
  anthropic: { color: '#cc785c', img: 'data:image/svg+xml;base64,' },
  openai: { color: '#1f1f1f', dark: '#e8e6e1', img: 'data:image/svg+xml;base64,' },
  kimi: { color: '#047afe', img: 'data:image/jpeg;base64,' },
  minimax: { color: '#eb3568', img: 'data:image/svg+xml;base64,' },
  zai: { color: '#1c7ff8', img: 'data:image/svg+xml;base64,' },
  xai: { color: '#736cd3', img: 'data:image/svg+xml;base64,' },
  deepseek: { color: '#2243e6', img: 'data:image/svg+xml;base64,' },
  alibaba: { color: '#ff7018', img: 'data:image/svg+xml;base64,' },
  google: { color: '#34a853', img: 'data:image/svg+xml;base64,' },
  meta: { color: '#0089f4', img: 'data:image/svg+xml;base64,' },
  mistral: { color: '#fd6f00', img: 'data:image/png;base64,' },
  cohere: { color: '#d18ee2', img: 'data:image/svg+xml;base64,' },
  nvidia: { color: '#76b900', img: 'data:image/svg+xml;base64,' },
  upstage: { color: '#7c59f5', img: 'data:image/svg+xml;base64,' },
  'sk-telecom': { color: '#e1002a', img: 'data:image/svg+xml;base64,' },
  lg: { color: '#df3b8a', img: 'data:image/png;base64,' },
  'thinking-machines': { color: '#676767', img: 'data:image/svg+xml;base64,' },
  'motif-technologies': { color: '#6a93eb', img: 'data:image/svg+xml;base64,' },
};
const IS_DARK = matchMedia('(prefers-color-scheme: dark)').matches;
const brandColor = b => (IS_DARK && b.dark) ? b.dark : b.color;

/* 模型名 → 品牌：小写后按前缀命中（顺序即优先级），mmx 这类嵌入名用 includes */
const BRAND_MATCH = [
  ['claude', 'anthropic'], ['anthropic', 'anthropic'],
  ['kimi', 'kimi'], ['moonshot', 'kimi'], ['k2', 'kimi'], ['k3', 'kimi'],
  ['minimax', 'minimax'],
  ['glm', 'zai'], ['zhipu', 'zai'], ['zai', 'zai'],
  ['gpt', 'openai'], ['codex', 'openai'], ['openai', 'openai'], ['chatgpt', 'openai'],
  ['o1', 'openai'], ['o3', 'openai'], ['o4', 'openai'],
  ['grok', 'xai'],
  ['deepseek', 'deepseek'],
  ['qwen', 'alibaba'], ['qwq', 'alibaba'],
  ['gemini', 'google'],
  ['llama', 'meta'],
  ['mistral', 'mistral'], ['mixtral', 'mistral'], ['codestral', 'mistral'],
  ['cohere', 'cohere'], ['command', 'cohere'],
];
/* 模型名没命中时按来源兜底；ccs 是转发层，AA 无对应条目，不配默认品牌 */
const PROFILE_BRAND = { cco: 'anthropic', kimi: 'kimi', codex: 'openai', grok: 'xai' };
function brandOf(profile, model) {
  const m = (model || '').toLowerCase();
  if (m.includes('mmx')) return 'minimax';
  for (const [pat, key] of BRAND_MATCH) if (m.startsWith(pat)) return key;
  return PROFILE_BRAND[profile] || null;
}

// 行色（热力图格子、行内各处的着色都走这里）：各家直接用品牌表色；
// ccs 没有 AA 条目，用星爆 logo 的次主色青（主色橙与 cco 撞，弃用）；
// oc（OpenCode）是工具不是模型厂，AA 无条目，用官方品牌灰（深色主题换浅灰，
// 同 openai 的 dark 处理思路）
const COLORS = {
  cco: brandColor(BRAND.anthropic), codex: brandColor(BRAND.openai),
  kimi: brandColor(BRAND.kimi), grok: brandColor(BRAND.xai),
  ccs: '#50a0a0', oc: IS_DARK ? '#cfcecd' : '#4b4646',
};
function modelColor(profile, model) {
  const b = brandOf(profile, model);
  return b ? brandColor(BRAND[b]) : COLORS[profile];
}
/* 排行面板的大块填充（条 / 堆叠段 / 饼图扇区）不用满饱和原色：向面板底色混 15%，
   色相不动但硬度降下来，和细线低阴影的整体质感一致；混的是 var(--panel)，
   明暗两个主题各自适配。logo 等小面积点缀仍用原色，保证辨识度。 */
const soft = c => `color-mix(in srgb, ${c} 85%, var(--panel))`;
/* 行首 logo：ccs（转发层）和 oc（工具）品牌表里都没有，静态内嵌自有图；其余行从 BRAND 运行时补 */
const LOGOS = {
  ccs: 'data:image/png;base64,',
  // OpenCode 是工具不是模型厂，品牌表里没有。标用官方品牌资源（opencode.ai/brand
  // 的 opencode-brand-assets.zip）里的像素 O：官方浅底配色（#211E1E 环 + #4B4646 芯），
  // 外加 #F1ECEC 官方米白圆角底砖保证明暗主题都可读；路径就是官方 SVG 原样
  oc: 'data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'-30 -30 300 360\'><rect x=\'-30\' y=\'-30\' width=\'300\' height=\'360\' rx=\'60\' fill=\'%23F1ECEC\'/><path d=\'M180 240H60V120H180V240Z\' fill=\'%234B4646\'/><path d=\'M180 60H60V240H180V60ZM240 300H0V0H240V300Z\' fill=\'%23211E1E\'/></svg>',
};
LOGOS.cco = BRAND.anthropic.img;
LOGOS.codex = BRAND.openai.img;
LOGOS.kimi = BRAND.kimi.img;
LOGOS.grok = BRAND.xai.img;
/* 按模型排行的 logo：与 modelColor 同一套 brandOf 判定，命中哪家用哪家的 AA 标；
   没命中回落本来源的行首标（不再一律用 ccs 标，否则 oc 行会挂错 logo） */
function modelLogo(profile, model) {
  const b = brandOf(profile, model);
  return `<img class="mlogo" src="${b ? BRAND[b].img : (LOGOS[profile] || LOGOS.ccs)}" alt="">`;
}
